<?php defined('ABSPATH') || exit;
function mm_demo_image($filename,$title){
    $existing=get_posts(['post_type'=>'attachment','post_status'=>'inherit','posts_per_page'=>1,'meta_key'=>'_mm_demo_asset','meta_value'=>$filename]);if($existing)return $existing[0]->ID;
    $path=get_theme_file_path('/assets/images/'.$filename);if(!is_file($path))return 0;
    require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';
    $tmp=wp_tempnam($filename);copy($path,$tmp);$id=media_handle_sideload(['name'=>$filename,'tmp_name'=>$tmp],0,$title);
    if(is_wp_error($id))return 0;update_post_meta($id,'_mm_demo_asset',$filename);update_post_meta($id,'_wp_attachment_image_alt',$title.' — original unbranded demonstration imagery');return $id;
}
function mm_seed_store(){
    if(!class_exists('WooCommerce'))return new WP_Error('woocommerce_required','Activate WooCommerce before importing.');
    update_option('mm_demo_mode',1);update_option('blogname','MUNEEB MART');update_option('blogdescription','Your time. Your signature.');
    if(!get_option('mm_seeded')){update_option('woocommerce_currency','PKR');update_option('woocommerce_default_country','PK:PB');update_option('woocommerce_enable_guest_checkout','yes');update_option('woocommerce_enable_signup_and_login_from_checkout','yes');update_option('woocommerce_manage_stock','yes');update_option('woocommerce_price_num_decimals',0);update_option('woocommerce_calc_taxes','no');update_option('woocommerce_ship_to_countries','');update_option('woocommerce_allowed_countries','specific');update_option('woocommerce_specific_allowed_countries',['PK']);update_option('woocommerce_store_address','');update_option('woocommerce_store_city','');update_option('woocommerce_store_postcode','');update_option('woocommerce_enable_reviews','no');update_option('blog_public',0);}
    $images=['steel'=>mm_demo_image('steel.webp','Steel bracelet watch with a black dial'),'rose'=>mm_demo_image('rose.webp','Rose-tone bracelet watch with a champagne dial'),'leather'=>mm_demo_image('leather.webp','Brown leather strap watch on warm stone'),'editorial'=>mm_demo_image('editorial.webp','Leather watch editorial on sandstone')];
    $collections=[
        'mens-watches'=>["Men's Watches",'Classic silhouettes and contemporary details. Discover distinctive styles for every day and every occasion.','steel'],
        'womens-watches'=>["Women's Watches",'Refined proportions, considered finishes, and a quiet kind of confidence. Find a watch that is entirely yours.','rose'],
        'luxury-inspired'=>['Luxury-Inspired','A study in elevated aesthetics. Distinctive designs without affiliation to any established watch brand.','rose'],
        'chronograph'=>['Chronograph Style','Layered dial aesthetics and technical inspiration. All demonstration specifications are illustrative; chronograph functionality is unverified.','steel'],
        'minimalist'=>['Minimalist Watches','Less, thoughtfully considered. Clean dials and understated designs for a modern point of view.','leather'],
        'classic'=>['Classic Collection','Timeless in spirit. Traditional watch styles that move effortlessly from work to an evening out.','leather'],
        'sports'=>['Sports-Inspired','An active aesthetic and confident proportions. No performance or water-resistance claims are made for demonstration watches.','steel'],
        'new-arrivals'=>['New Arrivals','A fresh perspective on personal style. Explore the most recently published watches, automatically updated.','rose'],
        'gifts'=>['The Gift Edit','A thoughtful way to mark a moment. Explore distinctive timepieces for birthdays, anniversaries, and just because.','leather']
    ];
    $cat_ids=[];foreach($collections as $slug=>$data){$term=term_exists($slug,'product_cat');if(!$term)$term=wp_insert_term($data[0],'product_cat',['slug'=>$slug,'description'=>$data[1]]);if(!is_wp_error($term)){$cat_ids[$slug]=(int)$term['term_id'];if(!get_term_meta($cat_ids[$slug],'thumbnail_id',true))update_term_meta($cat_ids[$slug],'thumbnail_id',$images[$data[2]]);}}
    $attributes=['watch-type'=>'Watch type','strap-material'=>'Strap material','dial-color'=>'Dial color','case-color'=>'Case color'];
    foreach($attributes as $slug=>$label){if(!wc_attribute_taxonomy_id_by_name($slug)){wc_create_attribute(['name'=>$label,'slug'=>$slug,'type'=>'select','order_by'=>'menu_order','has_archives'=>false]);}if(!taxonomy_exists('pa_'.$slug))register_taxonomy('pa_'.$slug,['product'],['hierarchical'=>false,'show_ui'=>false,'query_var'=>true,'public'=>true]);}delete_transient('wc_attribute_taxonomies');
    $data=json_decode(file_get_contents(MM_CORE_DIR.'data/products.json'),true);$featured=0;
    foreach($data as $index=>$row){if(wc_get_product_id_by_sku($row['sku']))continue;
        $variable=$row['variable']??false;$product=$variable?new WC_Product_Variable():new WC_Product_Simple();$product->set_name($row['name']);$product->set_slug(sanitize_title($row['name']));$product->set_sku($row['sku']);$product->set_status('publish');$product->set_catalog_visibility('visible');$product->set_short_description($row['short']);$product->set_description('<p>'.$row['description'].'</p><p><strong>Demonstration product.</strong> This fictional watch, its price, stock, imagery, and specifications are sample content for store testing. Actual materials, dimensions, movement, and functionality must be verified before sale. Imagery represents the design direction and may not match each sample attribute.</p>');$product->set_category_ids(array_values(array_intersect_key($cat_ids,array_flip($row['collections']))));$product->set_image_id($images[$row['image']]);$product->set_gallery_image_ids([$images['editorial']]);$product->set_reviews_allowed(false);$product->set_featured($index<4);$product->set_date_created(time()-($index*3600));
        $attrs=[];foreach($row['attributes'] as $slug=>$value){$tax='pa_'.$slug;$term=term_exists($value,$tax);if(!$term)$term=wp_insert_term($value,$tax);if(is_wp_error($term))continue;$attr=new WC_Product_Attribute();$attr->set_id(wc_attribute_taxonomy_id_by_name($slug));$attr->set_name($tax);$attr->set_options([(int)$term['term_id']]);$attr->set_visible(true);$attrs[]=$attr;}
        if($variable){$color=new WC_Product_Attribute();$color->set_name('Finish');$color->set_options(['Silver','Gold']);$color->set_visible(true);$color->set_variation(true);$attrs[]=$color;$product->set_default_attributes(['finish'=>'Silver']);}
        $product->set_category_ids(array_merge($product->get_category_ids(),[$cat_ids['new-arrivals']]));
        $product->set_attributes($attrs);
        if(!$variable){$product->set_regular_price($row['price']);$product->set_manage_stock(true);$product->set_stock_quantity($row['stock']);$product->set_stock_status($row['stock']>0?'instock':'outofstock');}
        $product->update_meta_data('_mm_demo','yes');$id=$product->save();
        if($variable){foreach(['Silver','Gold'] as $variation_index=>$finish){$variation=new WC_Product_Variation();$variation->set_parent_id($id);$variation->set_attributes(['finish'=>$finish]);$variation->set_sku($row['sku'].'-'.strtoupper(substr($finish,0,1)));$variation->set_regular_price($row['price']+$variation_index*500);$variation->set_manage_stock(true);$variation->set_stock_quantity(8);$variation->set_image_id($images[$variation_index?'rose':'steel']);$variation->save();}WC_Product_Variable::sync($id);}
    }
    $about='<img src="'.esc_url(get_theme_file_uri('/assets/images/editorial.webp')).'" alt="An unbranded leather watch on warm sandstone" width="1200" height="800"><p class="eyebrow">OUR POINT OF VIEW</p><h2>The art of timeless style.</h2><p>MUNEEB MART is built around a simple belief: the right timepiece can transform an everyday look into a lasting impression. We bring together distinctive designs, considered aesthetics, and an effortless shopping experience.</p><h2>Style is personal.</h2><p>A polished bracelet. The warmth of a leather strap. A clean dial with nothing to prove. We look for watches that make a quiet statement, and give you the freedom to choose what that statement says.</p><h2>A considered collection.</h2><p>Our vision is a boutique that is easy to explore and a pleasure to return to. A place for familiar classics, new perspectives, and thoughtful gifts. Every collection begins with a point of view: fewer distractions, more attention to the details.</p><h2>Here for the details.</h2><p>Clear product information, straightforward navigation, and a personal connection with our customers guide the experience we are building. This development store introduces that vision through fictional watches and illustrative imagery.</p><p><a class="button" href="'.esc_url(home_url('/catalog/')).'">Explore the collection →</a></p>';
    $policy_intro='<p><strong>Development policy draft — owner approval required.</strong> This store is a demonstration. Products, prices, inventory, and specifications are illustrative. Test orders do not collect payments and are not fulfilled.</p>';
    $pages=[
        'home'=>['Home',''], 'catalog'=>['All watches',''],
        'collections'=>['The collections','[mm_collections]'],
        'about-us'=>['Our story',$about], 'contact-us'=>['Let’s talk.','[mm_contact]'],
        'wishlist'=>['A collection of your own.','[mm_wishlist]'],
        'cart'=>['Your shopping bag','[woocommerce_cart]'], 'checkout'=>['The finishing touch.','[woocommerce_checkout]'], 'my-account'=>['Your account','[woocommerce_my_account]'],
        'privacy-policy'=>['Privacy policy',$policy_intro.'<h2>Information we collect</h2><p>WooCommerce stores the customer, order, billing, and shipping details you submit. Our contact form stores your name, email, optional phone number, message, and consent timestamp in the WordPress dashboard. Our newsletter stores your email and consent timestamp. Required cookies maintain your shopping cart and account session. Your wishlist is stored locally in your browser.</p><h2>How it is used</h2><p>Enquiries are used to respond to your requests. Newsletter details are used only for collection updates you consent to receive. The mailing provider and retention period must be confirmed by the owner before launch. No advertising analytics are included in this version.</p><h2>Your choices</h2><p>You can request access, correction, deletion, or withdrawal of newsletter consent through the contact form using the subject “Privacy or unsubscribe request”. WordPress privacy export and erasure tools support our enquiry and subscriber records. Order records may need to be retained where applicable.</p><h2>Before launch</h2><p>The store owner must publish the legal business identity, privacy contact, retention periods, processors, applicable rights, and international transfer details. This draft must be reviewed for the actual business and jurisdiction.</p>'],
        'terms-conditions'=>['Terms & conditions',$policy_intro.'<h2>Using this development store</h2><p>You may browse the sample catalog and place development test orders. These orders are for testing only and create no obligation to deliver goods. Never enter real payment-card details into a test form.</p><h2>Product information</h2><p>Demonstration names are fictional. Sample photographs, prices, stock quantities, and attributes must be replaced with verified information before sale. No connection with an established luxury watch brand is implied.</p><h2>Before accepting real orders</h2><p>The owner must approve legal business identity, applicable law, pricing and taxes, order acceptance, payment methods, cancellation terms, dispute handling, warranties, and customer rights.</p>'],
        'shipping-policy'=>['Shipping policy',$policy_intro.'<h2>Delivery information</h2><p>Real shipping destinations, carriers, fees, dispatch times, and delivery estimates have not yet been approved. Available configured methods and their costs appear at checkout. We do not promise free delivery or a delivery timeframe.</p><h2>Development checkout</h2><p>A local development delivery method may be configured solely for testing. Nothing is dispatched for a test order.</p><h2>Questions</h2><p>Use our contact form for shipping enquiries. This draft must be completed before accepting real orders.</p>'],
        'return-refund-policy'=>['Returns & refunds',$policy_intro.'<h2>Return arrangements</h2><p>Return eligibility, time limits, item condition, return shipping responsibility, refund processing times, and any exceptions must be approved by the owner before launch. No additional return guarantee is offered by this draft.</p><h2>Getting in touch</h2><p>For an order enquiry, contact the store team with your order reference. Avoid sending sensitive financial information.</p><h2>Test orders</h2><p>Development orders collect no payment, so no refund is due. Cancel a test order in WooCommerce to verify stock restoration.</p>'],
        'frequently-asked-questions'=>['A few things you might ask.','<details><summary>Is this store accepting real orders?</summary><p>This is a development store. All products and prices are demonstration content. The test payment method creates a real WooCommerce test record without collecting money or dispatching a watch.</p></details><details><summary>How do I find a watch?</summary><p>Explore the collections or use the catalog filters to narrow your choice by style, strap material, dial, finish, and price.</p></details><details><summary>Can I save a watch for later?</summary><p>Use the heart on a product card. Your wishlist is saved in this browser and can be removed at any time.</p></details><details><summary>Are the technical specifications verified?</summary><p>No. Demo specifications and photographs illustrate the shopping experience. The owner must verify and replace them before sale.</p></details><details><summary>How do I contact MUNEEB MART?</summary><p>Use our contact form. Your message is saved for the store team. Published support email, phone, and business hours will be confirmed before launch.</p></details><details><summary>What are the shipping and return policies?</summary><p>Visit the shipping and returns pages for the current development drafts. Fees, timelines, and eligibility must be approved before production.</p></details>']
    ];
    $page_ids=[];foreach($pages as $slug=>$info){$page=get_page_by_path($slug);
        // A fresh WordPress installation includes an unpublished default privacy page.
        // Replace only that untouched default, preserving drafts the owner has edited.
        if($page&&$slug==='privacy-policy'&&$page->post_status==='draft'&&!get_post_meta($page->ID,'_edit_last',true)&&str_contains($page->post_content,'Who we are')){wp_update_post(wp_slash(['ID'=>$page->ID,'post_status'=>'publish','post_content'=>$info[1]]));}
        // Use the supported classic cart/checkout for this lightweight PHP theme and gateway.
        if($page&&in_array($slug,['cart','checkout'],true)&&!get_post_meta($page->ID,'_edit_last',true)&&str_contains($page->post_content,'wp:woocommerce/'.$slug)){wp_update_post(wp_slash(['ID'=>$page->ID,'post_content'=>$info[1]]));}
        $page_ids[$slug]=$page?$page->ID:wp_insert_post(wp_slash(['post_type'=>'page','post_status'=>'publish','post_name'=>$slug,'post_title'=>$info[0],'post_content'=>$info[1]]));}
    update_option('show_on_front','page');update_option('page_on_front',$page_ids['home']);foreach(['shop'=>'catalog','cart'=>'cart','checkout'=>'checkout','myaccount'=>'my-account'] as $option=>$slug)update_option('woocommerce_'.$option.'_page_id',$page_ids[$slug]);update_option('woocommerce_terms_page_id',$page_ids['terms-conditions']);update_option('wp_page_for_privacy_policy',$page_ids['privacy-policy']);
    update_option('woocommerce_permalinks',['product_base'=>'/product','category_base'=>'collections','tag_base'=>'product-tag','attribute_base'=>'']);update_option('permalink_structure','/%postname%/');
    if(!wp_get_nav_menu_object('MUNEEB MART primary')){$menu=wp_create_nav_menu('MUNEEB MART primary');foreach(['home'=>'Home','catalog'=>'Catalog','collections'=>'Collections','about-us'=>'About Us','contact-us'=>'Contact'] as $slug=>$label)wp_update_nav_menu_item($menu,0,['menu-item-title'=>$label,'menu-item-object'=>'page','menu-item-object-id'=>$page_ids[$slug],'menu-item-type'=>'post_type','menu-item-status'=>'publish']);$locations=get_theme_mod('nav_menu_locations',[]);$locations['primary']=$menu;set_theme_mod('nav_menu_locations',$locations);}
    update_option('mm_seeded',1);flush_rewrite_rules();wc_delete_product_transients();return true;
}
